INSERT INTO "EC_Question" (id, text, type, "skillId", options, "correctAnswer", points) VALUES
('js-q1', 'What is the output of typeof null?', 'MCQ', '2442717f-08f9-4391-a7ad-70f5b6237fc3', '["object","null","undefined","number"]'::json, 'object', 10),
('js-q2', 'Which keyword is used to define a constant in ES6?', 'MCQ', '2442717f-08f9-4391-a7ad-70f5b6237fc3', '["const","let","var","constant"]'::json, 'const', 10),
('js-q3', 'What does NaN stand for?', 'MCQ', '2442717f-08f9-4391-a7ad-70f5b6237fc3', '["Not a Number","New and Nice","Next and Now","No absolute Number"]'::json, 'Not a Number', 10),
('react-q1', 'What does React.memo do?', 'MCQ', '3502e432-fa33-4f7b-898a-748c24e2aeee', '["Caches a value","Prevents unnecessary re-renders","Manages state","Handles side effects"]'::json, 'Prevents unnecessary re-renders', 10),
('react-q2', 'Which hook should be used to memoize a function?', 'MCQ', '3502e432-fa33-4f7b-898a-748c24e2aeee', '["useMemo","useRef","useCallback","useEffect"]'::json, 'useCallback', 10),
('react-q3', 'Where should you place calculations in a functional component?', 'MCQ', '3502e432-fa33-4f7b-898a-748c24e2aeee', '["useMemo","useEffect","useState","Inside render"]'::json, 'useMemo', 10),
('node-q1', 'Which core module is used for handling file paths?', 'MCQ', '7b8e63ee-8620-4c05-9747-ea83e3ad2bfc', '["fs","path","url","os"]'::json, 'path', 10),
('node-q2', 'What is the default port for an Express server?', 'MCQ', '7b8e63ee-8620-4c05-9747-ea83e3ad2bfc', '["3000","5000","8080","None"]'::json, 'None', 10),
('node-q3', 'Which module provides basic cryptographic functionality?', 'MCQ', '7b8e63ee-8620-4c05-9747-ea83e3ad2bfc', '["crypto","security","hash","encrypt"]'::json, 'crypto', 10),
('sql-q1', 'Which keyword is used to sort results in SQL?', 'MCQ', '484d836f-c59f-4ef2-92c9-48bf995791dd', '["SORT BY","ORDER BY","GROUP BY","ARRANGE"]'::json, 'ORDER BY', 10),
('sql-q2', 'Which JOIN returns all records from the left table?', 'MCQ', '484d836f-c59f-4ef2-92c9-48bf995791dd', '["INNER JOIN","RIGHT JOIN","LEFT JOIN","FULL JOIN"]'::json, 'LEFT JOIN', 10),
('sql-q3', 'What is the primary key typically used for?', 'MCQ', '484d836f-c59f-4ef2-92c9-48bf995791dd', '["Sorting","Indexing","Uniquely identifying a row","Nothing"]'::json, 'Uniquely identifying a row', 10),
('8bb5ebda-360c-4574-8419-92b404afbc34', 'Which of the following methods is used to add an element to the end of a JavaScript array?', 'MCQ', '2442717f-08f9-4391-a7ad-70f5b6237fc3', '["push()","pop()","shift()","unshift()"]'::json, 'push()', 10),
('edcf6b11-e5a2-4c04-a02d-d7d8fa35c0cf', 'What is the purpose of the ''let'' keyword in JavaScript?', 'MCQ', '2442717f-08f9-4391-a7ad-70f5b6237fc3', '["To declare a global variable","To declare a constant variable","To declare a block-scoped variable","To declare a function"]'::json, 'To declare a block-scoped variable', 10),
('d8306bd4-f26a-420b-989f-26bc466ebcf4', 'What is the difference between ''null'' and ''undefined'' in JavaScript?', 'MCQ', '2442717f-08f9-4391-a7ad-70f5b6237fc3', '["Null is an object, while undefined is a primitive value","Null is a primitive value, while undefined is an object","Null represents the absence of a value, while undefined represents an uninitialized variable","Null represents an uninitialized variable, while undefined represents the absence of a value"]'::json, 'Null represents the absence of a value, while undefined represents an uninitialized variable', 10),
('1728b20e-aad4-47cb-b5f5-f42069a03664', 'What is the purpose of the ''bind()'' method in JavaScript?', 'MCQ', '2442717f-08f9-4391-a7ad-70f5b6237fc3', '["To invoke a function immediately","To change the context of a function","To create a new function with the same behavior as the original","To prevent a function from being invoked"]'::json, 'To change the context of a function', 10),
('03fa8744-121a-44e2-b6ec-45235b5f6e7c', 'Which of the following is a valid way to create a new object in JavaScript?', 'MCQ', '2442717f-08f9-4391-a7ad-70f5b6237fc3', '["Using the 'new' keyword with a constructor function","Using the 'Object.create()' method","Using the 'JSON.parse()' method","Using the 'eval()' function"]'::json, 'Using the ''new'' keyword with a constructor function', 10),
('11dd1c05-c519-4697-956a-257ef5c17470', 'Which SQL statement is used to add a new column to an existing table?', 'MCQ', '484d836f-c59f-4ef2-92c9-48bf995791dd', '["ALTER TABLE","CREATE TABLE","DROP TABLE","TRUNCATE TABLE"]'::json, 'ALTER TABLE', 10),
('251111c0-8ad4-4f7c-8138-9e83ec5fa28a', 'What is the purpose of the HAVING clause in SQL?', 'MCQ', '484d836f-c59f-4ef2-92c9-48bf995791dd', '["To specify the conditions for selecting data","To group data based on one or more columns","To filter grouped data based on a condition","To sort data in ascending or descending order"]'::json, 'To filter grouped data based on a condition', 10),
('a5af9290-465f-4d60-84ab-14336de8c3b2', 'What is the difference between INNER JOIN and LEFT JOIN in SQL?', 'MCQ', '484d836f-c59f-4ef2-92c9-48bf995791dd', '["INNER JOIN returns all rows, while LEFT JOIN returns only matching rows","INNER JOIN returns only matching rows, while LEFT JOIN returns all rows from the left table","INNER JOIN is used for aggregating data, while LEFT JOIN is used for filtering data","INNER JOIN is used for sorting data, while LEFT JOIN is used for grouping data"]'::json, 'INNER JOIN returns only matching rows, while LEFT JOIN returns all rows from the left table', 10),
('88c1c703-1b3d-4529-a6c4-43577a58507d', 'What is the difference between WHERE and HAVING clauses in SQL?', 'MCQ', '484d836f-c59f-4ef2-92c9-48bf995791dd', '["WHERE is used for filtering grouped data, while HAVING is used for filtering individual rows","WHERE is used for filtering individual rows, while HAVING is used for filtering grouped data","WHERE is used for sorting data, while HAVING is used for grouping data","WHERE is used for aggregating data, while HAVING is used for filtering data"]'::json, 'WHERE is used for filtering individual rows, while HAVING is used for filtering grouped data', 10),
('f3e729da-70ce-424a-b191-2c78be4b0cc6', 'What is the purpose of the GROUP BY clause in SQL?', 'MCQ', '484d836f-c59f-4ef2-92c9-48bf995791dd', '["To filter data based on a condition","To sort data in ascending or descending order","To group data based on one or more columns","To add a new column to an existing table"]'::json, 'To group data based on one or more columns', 10),
('8dd51bfb-6640-4552-97fe-a0d08972422e', 'Which SQL function is used to calculate the average value of a column?', 'MCQ', '484d836f-c59f-4ef2-92c9-48bf995791dd', '["SUM","AVG","MAX","MIN"]'::json, 'AVG', 10),
('38b51989-499e-471d-87dd-3694e80addc5', 'Which SQL statement is used to delete all rows from a table?', 'MCQ', '484d836f-c59f-4ef2-92c9-48bf995791dd', '["DELETE","TRUNCATE","DROP","INSERT"]'::json, 'TRUNCATE', 10),
('7ca1a37f-136d-4a70-94f6-301f0e536243', 'What is the purpose of the ORDER BY clause in SQL?', 'MCQ', '484d836f-c59f-4ef2-92c9-48bf995791dd', '["To filter data based on a condition","To group data based on one or more columns","To sort data in ascending or descending order","To add a new column to an existing table"]'::json, 'To sort data in ascending or descending order', 10),
('0af9f987-c6b1-447a-a3d0-0d0fb7d4b440', 'Which SQL statement is used to create a copy of an existing table?', 'MCQ', '484d836f-c59f-4ef2-92c9-48bf995791dd', '["CREATE TABLE","SELECT INTO","INSERT INTO","UPDATE TABLE"]'::json, 'SELECT INTO', 10),
('47d3174e-71a0-44ad-bf10-c5bcc2c68c07', 'Which SQL function is used to concatenate two or more strings?', 'MCQ', '484d836f-c59f-4ef2-92c9-48bf995791dd', '["CONCAT","JOIN","UNION","MERGE"]'::json, 'CONCAT', 10),
('f7ea1817-9a5e-4cd9-ae4b-c3e3ecff8560', 'What is the purpose of the ''let'' keyword in JavaScript?', 'MCQ', '2442717f-08f9-4391-a7ad-70f5b6237fc3', '["To declare a global variable","To declare a constant variable","To declare a block scopied variable","To declare a function"]'::json, 'To declare a block scopied variable', 10),
('f351e6a1-f6ac-473c-8761-81ed71916cdf', 'What is the difference between ''null'' and ''undefined'' in JavaScript?', 'MCQ', '2442717f-08f9-4391-a7ad-70f5b6237fc3', '["Null is an object, undefined is not","Null is a number, undefined is a string","Null represents an empty object, undefined represents an uninitialized variable","Null and undefined are the same"]'::json, 'Null represents an empty object, undefined represents an uninitialized variable', 10),
('08cc46a8-1c3e-4370-90c5-82936d774142', 'What is the purpose of the ''map()'' function in JavaScript?', 'MCQ', '2442717f-08f9-4391-a7ad-70f5b6237fc3', '["To filter an array","To transform an array","To sort an array","To reverse an array"]'::json, 'To transform an array', 10),
('66418dee-a758-423d-883c-86d9a4df199a', 'What is the purpose of the ''async/await'' syntax in JavaScript?', 'MCQ', '2442717f-08f9-4391-a7ad-70f5b6237fc3', '["To handle synchronous code","To handle asynchronous code","To handle errors","To handle callbacks"]'::json, 'To handle asynchronous code', 10),
('94ceef9e-26c9-496b-8e24-477655f3253b', 'What is the difference between the ''=='' and ''==='' operators in JavaScript?', 'MCQ', '2442717f-08f9-4391-a7ad-70f5b6237fc3', '["'==' checks for equality, '===' checks for identity","'==' checks for identity, '===' checks for equality","'==' checks for type and value, '===' checks for value only","'==' checks for value only, '===' checks for type and value"]'::json, '''=='' checks for value only, ''==='' checks for type and value', 10),
('4f996c04-a37f-4781-8dd2-bb9442e830e0', 'What is the purpose of the ''try/catch'' block in JavaScript?', 'MCQ', '2442717f-08f9-4391-a7ad-70f5b6237fc3', '["To handle asynchronous code","To handle synchronous code","To handle errors","To handle callbacks"]'::json, 'To handle errors', 10),
('e44bcab0-7f07-49c0-bd6c-a234f073fb1c', 'What is the purpose of the ''JSON.parse()'' function in JavaScript?', 'MCQ', '2442717f-08f9-4391-a7ad-70f5b6237fc3', '["To convert a string to a JSON object","To convert a JSON object to a string","To parse a JSON string","To validate a JSON object"]'::json, 'To convert a string to a JSON object', 10),
('a6403f1c-447e-4210-8259-d5cbb3e7dcb8', 'What is Node.js?', 'MCQ', '7b8e63ee-8620-4c05-9747-ea83e3ad2bfc', '["A JavaScript framework","A JavaScript library","A JavaScript runtime environment","A JavaScript compiler"]'::json, 'A JavaScript runtime environment', 10),
('592bd471-37b3-4e2d-b7d2-73e55d077399', 'Which of the following is a popular Node.js framework?', 'MCQ', '7b8e63ee-8620-4c05-9747-ea83e3ad2bfc', '["React","Angular","Express.js","Vue.js"]'::json, 'Express.js', 10),
('e8c05e3e-7a6c-44de-94b6-3a6140f42b7c', 'What is the purpose of the ''require'' function in Node.js?', 'MCQ', '7b8e63ee-8620-4c05-9747-ea83e3ad2bfc', '["To import a module","To export a module","To create a new module","To delete a module"]'::json, 'To import a module', 10),
('19fde6ea-bd0f-4413-9f2c-460f1fe1ed53', 'What is the difference between ''let'' and ''const'' in Node.js?', 'MCQ', '7b8e63ee-8620-4c05-9747-ea83e3ad2bfc', '["'let' is used for constants, 'const' is used for variables","'let' is used for variables, 'const' is used for constants","'let' is used for functions, 'const' is used for classes","'let' is used for classes, 'const' is used for functions"]'::json, '''let'' is used for variables, ''const'' is used for constants', 10),
('5ea96c88-b006-476a-9c93-810159931600', 'What is the purpose of the ''package.json'' file in a Node.js project?', 'MCQ', '7b8e63ee-8620-4c05-9747-ea83e3ad2bfc', '["To store project dependencies","To store project configuration","To store project code","To store project documentation"]'::json, 'To store project dependencies', 10),
('c79492c5-7eec-4ea6-b39a-fd1366de3b42', 'What is the command to install a new package in Node.js using npm?', 'MCQ', '7b8e63ee-8620-4c05-9747-ea83e3ad2bfc', '["npm install","npm uninstall","npm update","npm remove"]'::json, 'npm install', 10),
('a47a1f17-0b89-44c8-92b0-0967f2d021a4', 'What is the purpose of the ''async/await'' syntax in Node.js?', 'MCQ', '7b8e63ee-8620-4c05-9747-ea83e3ad2bfc', '["To handle synchronous code","To handle asynchronous code","To handle parallel code","To handle concurrent code"]'::json, 'To handle asynchronous code', 10),
('c9d0195d-7cb9-4c4a-bbb7-05c0ed7f476a', 'What is the primary purpose of the ''npm'' command in Node.js?', 'MCQ', '7b8e63ee-8620-4c05-9747-ea83e3ad2bfc', '["To create a new Node.js project","To manage dependencies and packages for a Node.js project","To start a Node.js server","To debug a Node.js application"]'::json, 'To manage dependencies and packages for a Node.js project', 10),
('d0cac3f0-b3ed-4619-9ab5-371cc7ea7f07', 'Which Node.js module is used for file system operations?', 'MCQ', '7b8e63ee-8620-4c05-9747-ea83e3ad2bfc', '["HTTP","FS","Path","URL"]'::json, 'FS', 10),
('193c6063-f030-41d2-9b30-fd2ae692598e', 'What is the event-driven I/O model used by Node.js?', 'MCQ', '7b8e63ee-8620-4c05-9747-ea83e3ad2bfc', '["Asynchronous","Synchronous","Multi-threaded","Single-threaded"]'::json, 'Asynchronous', 10),
('229b5c66-8943-4cb8-abda-f3a93f07d491', 'Which of the following is a popular Node.js framework for building web applications?', 'MCQ', '7b8e63ee-8620-4c05-9747-ea83e3ad2bfc', '["React","Angular","Express","Vue.js"]'::json, 'Express', 10),
('bbbd2810-5f6a-48ce-a2d5-6ad318b49671', 'What is the purpose of the ''require'' function in Node.js?', 'MCQ', '7b8e63ee-8620-4c05-9747-ea83e3ad2bfc', '["To create a new object","To import a module or package","To start a Node.js server","To debug a Node.js application"]'::json, 'To import a module or package', 10),
('6f322828-c649-46ae-b6ce-0dd669732a7a', 'What is the purpose of the ''let'' keyword in JavaScript?', 'MCQ', '2442717f-08f9-4391-a7ad-70f5b6237fc3', '["To declare a global variable","To declare a constant variable","To declare a block-scoped variable","To declare a function"]'::json, 'To declare a block-scoped variable', 10),
('8d662177-3b88-4e4a-9820-4a8f2088a79a', 'Which of the following is a JavaScript framework used for building user interfaces?', 'MCQ', '2442717f-08f9-4391-a7ad-70f5b6237fc3', '["React","Angular","Vue.js","All of the above"]'::json, 'All of the above', 10),
('223eb04c-0d4b-4cf6-89ab-fd158f86e212', 'What is the difference between ''null'' and ''undefined'' in JavaScript?', 'MCQ', '2442717f-08f9-4391-a7ad-70f5b6237fc3', '["'null' represents an empty object, while 'undefined' represents an uninitialized variable","'null' represents an uninitialized variable, while 'undefined' represents an empty object","'null' represents a variable that has been explicitly set to nothing, while 'undefined' represents a variable that has not been declared","'null' and 'undefined' are the same thing"]'::json, '''null'' represents a variable that has been explicitly set to nothing, while ''undefined'' represents a variable that has not been declared', 10),
('e3556fd1-54d1-4280-9c35-fb0ee23ab12c', 'Which of the following JavaScript methods is used to add an event listener to an element?', 'MCQ', '2442717f-08f9-4391-a7ad-70f5b6237fc3', '["addEventListener()","attachEvent()","addListener()","addEventHandler()"]'::json, 'addEventListener()', 10),
('bb6ffbce-7c1a-44bf-961d-752fe179cb9b', 'What is the purpose of the ''finally'' block in a JavaScript try-catch statement?', 'MCQ', '2442717f-08f9-4391-a7ad-70f5b6237fc3', '["To catch and handle exceptions","To specify code that should run regardless of whether an exception was thrown","To specify code that should only run if an exception was thrown","To skip over code that might throw an exception"]'::json, 'To specify code that should run regardless of whether an exception was thrown', 10);
